protected static double GetEpicInvitationDropRate()
	{
		double num = 0.02;
		double num2 = GameWorld.instance.PlayerProfile.GetResidentEffects<RecruitmentResidentEffect>().Sum((RecruitmentResidentEffect r) => r.Chance);
		if (num2 > 5.0)
		{
			num2 = 5.0;
		}
		return num * (1.0 + num2);
	}

