protected List<ResourceUpdate> GenerateScrollMats(ResourceType type, DifficultyLevelMeasurement measurement)
	{
		double num = 0.0;
		double? achievedDifficultyValue = GameWorld.instance.PlayerProfile.AchievedDifficultyValue;
		if (achievedDifficultyValue.HasValue && achievedDifficultyValue.GetValueOrDefault() > 140.0)
		{
			if (measurement.StarRating == 1)
			{
				num = ((measurement.DifficultyValue <= 100.0) ? 0.01 : ((!(measurement.DifficultyValue <= 200.0)) ? 0.1 : 0.05));
			}
			if (measurement.StarRating > 1)
			{
				num = ((measurement.DifficultyValue <= 80.0) ? 0.12 : ((!(measurement.DifficultyValue <= 180.0)) ? 0.3 : 0.18));
			}
		}
		if ((double)UnityEngine.Random.value <= num)
		{
			List<ResourceUpdate> list = new List<ResourceUpdate>();
			list.Add(new ResourceUpdate
			{
				ResourceType = type,
				ChangeAmount = 1.0,
				RelatedItems = new List<Item>()
			});
			return list;
		}
		return new List<ResourceUpdate>();
	}

public sealed override UnitGrowthProfile GetMonsterGrowthProfile(DifficultyLevelMeasurement measurement)
	{
		UnitGrowthProfile growthProfile = CorrespondingClassStyle.GetStyleConfig().GetGrowthProfile(measurement);
		growthProfile.SetValue(AttributeType.HitRateAdjustment, 0.02);
		AttributeType type = ((CorrespondingClassStyle.GetClassCategory() != ClassCategory.CasterAssassin) ? AttributeType.Strength : AttributeType.Intelligience);
		double num = growthProfile.UnitGrowthValues.Where((UnitGrowthValue v) => v.AttributeType == AttributeType.Intelligience || v.AttributeType == AttributeType.Strength).Sum((UnitGrowthValue a) => a.Potential);
		double num2 = growthProfile.UnitGrowthValues.Where((UnitGrowthValue v) => v.AttributeType == AttributeType.Vitality).Sum((UnitGrowthValue a) => a.Potential);
		double num3 = growthProfile.UnitGrowthValues.Where((UnitGrowthValue v) => v.AttributeType == AttributeType.Agility).Sum((UnitGrowthValue a) => a.Potential);
		if (measurement.StarRating == 1)
