public int GetMonsterLevel(AdventureEncounterSlotType type)
	{
		int num = 1;
		if (TestingProcessor.InTesting)
		{
			return 1;
		}
		if (StarRating == 1)
		{
			num = ((DifficultyValue <= 60.0) ? ((int)Math.Ceiling(DifficultyValue / 1.5)) : ((!(DifficultyValue <= 120.0)) ? (80 + (int)Math.Ceiling((DifficultyValue - 120.0) / 10.0)) : (40 + (int)Math.Ceiling((DifficultyValue - 60.0) / 1.5))));
		}
		if (StarRating == 2)
		{
			num = ((!(DifficultyValue <= 120.0)) ? (92 + (int)Math.Ceiling((DifficultyValue - 120.0) / 13.0)) : (80 + (int)Math.Ceiling(DifficultyValue / 10.0)));
		}
		if (StarRating == -1)
		{
			num = ((DifficultyValue <= 100.0) ? (90 + (int)Math.Ceiling(DifficultyValue / 20.0)) : ((DifficultyValue <= 200.0) ? (95 + (int)Math.Ceiling((DifficultyValue - 100.0) / 50.0)) : ((!(DifficultyValue <= 300.0)) ? (98 + (int)Math.Ceiling((DifficultyValue - 300.0) / 50.0)) : 98)));
		}
		if (type == AdventureEncounterSlotType.MiniBoss)
		{
			num += 2;
		}
		if (type == AdventureEncounterSlotType.Boss)
		{
			num += 3;
		}
		return num;
	}

public GenerationDistribution GetDefaultItemGenerationDistribution(ResourceSourceType itemSource)
	{
		switch (itemSource)
		{
		case ResourceSourceType.BuildingProduction:
			return new GenerationDistribution(0.1, 0.02, 0.004, 0.0002);
		case ResourceSourceType.Exploration:
			return new GenerationDistribution(0.05, 0.07, 0.1, 0.0004);
		case ResourceSourceType.DungeonDrop:
		case ResourceSourceType.ShopPurchase:
			if (StarRating == 1 && DifficultyValue <= 100.0)
			{
				return new GenerationDistribution(0.1, 0.04, 0.02, 0.01);
			}
			if (StarRating == 1)
			{
				return new GenerationDistribution(0.1, 0.05, 0.01, 0.0005);
			}
			return new GenerationDistribution(0.1, 0.05, 0.02, 0.001);
		default:
			return new GenerationDistribution(0.1, 0.02, 0.004, 0.0002);
		}
	}

