public GenerationDistribution GetGradedChestGeneration(QualityGrade grade)
	{
		if (StarRating == 1 && DifficultyValue <= 100.0)
		{
			return grade switch
			{
				QualityGrade.Normal => GetDefaultItemGenerationDistribution(ResourceSourceType.DungeonDrop), 
				QualityGrade.Rare => new GenerationDistribution(0.6, 0.02, 0.01, 0.001), 
				QualityGrade.Epic => new GenerationDistribution(0.2, 0.5, 0.01, 0.001), 
				QualityGrade.Legendary => new GenerationDistribution(0.1, 0.2, 0.5, 0.001), 
				QualityGrade.Ancient => new GenerationDistribution(0.1, 0.1, 0.1, 0.5), 
				_ => null, 
			};
		}
		if (StarRating == 1)
		{
			return grade switch
			{
				QualityGrade.Normal => GetDefaultItemGenerationDistribution(ResourceSourceType.DungeonDrop), 
				QualityGrade.Rare => new GenerationDistribution(0.5, 0.01, 0.005, 0.001), 
				QualityGrade.Epic => new GenerationDistribution(0.5, 0.3, 0.01, 0.001), 
				QualityGrade.Legendary => new GenerationDistribution(0.4, 0.1, 0.3, 0.001), 
				QualityGrade.Ancient => new GenerationDistribution(0.01, 0.01, 0.5, 0.3), 
				_ => null, 
			};
		}
		if (StarRating == 2)
		{
			return grade switch
			{
				QualityGrade.Normal => GetDefaultItemGenerationDistribution(ResourceSourceType.DungeonDrop), 
				QualityGrade.Rare => new GenerationDistribution(0.4, 0.02, 0.01, 0.0005), 
				QualityGrade.Epic => new GenerationDistribution(0.4, 0.2, 0.01, 0.001), 
				QualityGrade.Legendary => new GenerationDistribution(0.1, 0.2, 0.2, 0.005), 
				QualityGrade.Ancient => new GenerationDistribution(0.1, 0.1, 0.4, 0.01), 
				_ => null, 
			};
		}
		return grade switch
		{
			QualityGrade.Normal => GetDefaultItemGenerationDistribution(ResourceSourceType.DungeonDrop), 
			QualityGrade.Rare => new GenerationDistribution(0.4, 0.015, 0.001, 0.0005), 
			QualityGrade.Epic => new GenerationDistribution(0.3, 0.25, 0.001, 0.002), 
			QualityGrade.Legendary => new GenerationDistribution(0.1, 0.15, 0.3, 0.003), 
			QualityGrade.Ancient => new GenerationDistribution(0.1, 0.1, 0.4, 0.01), 
			_ => null, 
		};
	}

public static DifficultyLevelMeasurement GetDifficultyLevelMeasurementByValue(double difficultyvalue, int starrating)
	{
		DifficultyLevelMeasurement difficultyLevelMeasurement = new DifficultyLevelMeasurement();
		difficultyLevelMeasurement.DifficultyValue = difficultyvalue;
		difficultyLevelMeasurement.DifficultyTier = 1 + (int)Math.Floor(difficultyLevelMeasurement.DifficultyValue / DifficultyLevelToIndicatorCoefficient);
		difficultyLevelMeasurement.TierPowerness = (difficultyLevelMeasurement.DifficultyValue - (double)(difficultyLevelMeasurement.DifficultyTier - 1) * DifficultyLevelToIndicatorCoefficient) / DifficultyLevelToIndicatorCoefficient;
		difficultyLevelMeasurement.GemTier = GetGemLevel(difficultyvalue, starrating);
		difficultyLevelMeasurement.MonsterSkillLevel = 1;
		difficultyLevelMeasurement.MosnterPowerLevel = ((starrating == -1) ? GetMonsterPowerLevel_Endless(difficultyvalue) : ((starrating > 1) ? ((double)((starrating - 1) * 310) + GetMonsterPowerLevel_HigherStar(difficultyvalue)) : GetMonsterPowerLevel(difficultyvalue)));
		difficultyLevelMeasurement.CorrespondingReputation = difficultyLevelMeasurement.DifficultyValue * 100.0;
		difficultyLevelMeasurement.StarRating = starrating;
		return difficultyLevelMeasurement;
	}

