public List<ResourceUpdate> GenerateDropableWeapons(QualityGrade grade, int numberOfItems, bool forceStar = false)
	{
		List<DropTableParameter> presences = (from s in GetDifficultyRelevantWeapons(new List<ResourceSourceType> { ResourceSourceType.DungeonDrop })
			select new DropTableParameter
			{
				ResourceType = s,
				Presence = 100,
				Level = 1,
				InclusiveVolumTo = 1.0,
				InclusiveVolumFrom = 1.0
			}).ToList();
		return (from i in presences.WeightedRandomSelectMaxUniqueness((DropTableParameter a, DropTableParameter b) => a.ResourceType == b.ResourceType, numberOfItems)
			select new ResourceUpdate
			{
				ResourceType = i.ResourceType,
				ChangeAmount = 1.0,
				RelatedItems = new List<Item> { i.ResourceType.ItemGenerate(ResourceSourceType.DungeonDrop, itemTierLevel: GetCorrespondingItemTierLevel(i.ResourceType), quality: GetQualityConfig(grade, ResourceSourceType.DungeonDrop, i.ResourceType, forceStar)) }
			}).ToList();
	}

