				RelatedItems = new List<Item> { i.ResourceType.ItemGenerate(ResourceSourceType.DungeonDrop, itemTierLevel: GetCorrespondingItemTierLevel(i.ResourceType), quality: GetQualityConfig(determined, ResourceSourceType.DungeonDrop, i.ResourceType, forceStar)) }
			}).ToList();
	}

private ItemGenerationQuality GetQualityConfig(QualityGrade? determined, ResourceSourceType sourceType, ResourceType itemType, bool forceStar = false)
	{
		ResourceCategory resourceCategory = itemType.GetResourceCategory();
		int correspondingItemTierLevel = GetCorrespondingItemTierLevel(itemType);
		bool flag = ((resourceCategory.IsWeapon() || resourceCategory.IsArmor()) && correspondingItemTierLevel > 35) || (resourceCategory == ResourceCategory.Accessory && correspondingItemTierLevel > 35 && forceStar) || (resourceCategory == ResourceCategory.Scrolls && correspondingItemTierLevel > 35);
		if (flag && forceStar)
		{
			return ItemGenerationQuality.CreateStar();
		}
		if (determined.HasValue)
		{
			if (determined.Value == QualityGrade.Ancient && flag && (double)UnityEngine.Random.value <= GetStarChance(sourceType))
			{
				return ItemGenerationQuality.CreateStar();
			}
			return ItemGenerationQuality.CreateGraded(determined.Value);
		}
		GenerationDistribution defaultItemGenerationDistribution = GetDefaultItemGenerationDistribution(sourceType);
		double totalItemDropBoostRate = GameWorld.instance.PlayerProfile.GetTownStats().TotalItemDropBoostRate;
		defaultItemGenerationDistribution = defaultItemGenerationDistribution.BoostDrop(totalItemDropBoostRate);
		QualityGrade grade = defaultItemGenerationDistribution.GetGrade();
		if (grade == QualityGrade.Ancient && flag && (double)UnityEngine.Random.value <= GetStarChance(sourceType))
		{
			return ItemGenerationQuality.CreateStar();
		}
		return ItemGenerationQuality.CreateGraded(grade);
	}

