public List<UnitClass> GetPossibleMinionUnits()
	{
		List<UnitClass> list = new List<UnitClass>();
		foreach (AdventureType possibleAdventureType in GetPossibleAdventureTypes())
		{
			int highestLevelNumber = GetHighestLevelNumber(possibleAdventureType);
			if (highestLevelNumber != -1)
			{
				list.AddRange(from p in possibleAdventureType.GetConfiguration().GetPossibleMinionClasses(highestLevelNumber)
					select p.UnitClass);
			}
		}
		return list.Distinct().ToList();
	}

