public List<Commodity> GetShopItems(int numberOfItems)
	{
		List<Commodity> list = new List<Commodity>();
		List<DropTypePresence> list2 = new List<DropTypePresence>();
		list2.Add(new DropTypePresence
		{
			Presence = 100,
			DropType = DropType.Accessories
		});
		List<DropTypePresence> presences = list2;
		int numberOfDaysTillExpiration = 45;
		for (int i = 0; i < numberOfItems; i++)
		{
			DropType dropType = presences.WeightedRandomSelect().DropType;
			if (dropType == DropType.Accessories)
			{
				List<ResourceType> difficultyRelatedAccessories = GetDifficultyRelatedAccessories();
				if (difficultyRelatedAccessories.Any())
				{
					ResourceType randomSelection = GetRandomSelection(difficultyRelatedAccessories);
					ResourceType type = randomSelection;
					ResourceSourceType itemSource = ResourceSourceType.ShopPurchase;
					int correspondingItemTierLevel = GetCorrespondingItemTierLevel(randomSelection);
					Item item = type.ItemGenerate(itemSource, GetQualityConfig(null, ResourceSourceType.ShopPurchase, randomSelection), correspondingItemTierLevel);
					list.Add(new Commodity
					{
						ResourceType = item.Type,
						Amount = 1,
						Items = new List<Item> { item },
						PricePerItem = item.Value * 2.0 * (0.8 + 0.2 * (double)item.ItemGrade),
						NumberOfDaysTillExpiration = numberOfDaysTillExpiration
					});
				}
			}
		}
		return list;
	}

