		double num = growthProfile.UnitGrowthValues.Where((UnitGrowthValue v) => v.AttributeType == AttributeType.Intelligience || v.AttributeType == AttributeType.Strength).Sum((UnitGrowthValue a) => a.Potential);
		double num2 = growthProfile.UnitGrowthValues.Where((UnitGrowthValue v) => v.AttributeType == AttributeType.Vitality).Sum((UnitGrowthValue a) => a.Potential);
