public override List<ISpecialEffectDataLoad> GetSpecialEffectDataLoads(DifficultyLevelMeasurement relevantDifficultyLevelMeasurement)
	{
		List<ISpecialEffectDataLoad> specialEffectDataLoads = CorrespondingClassStyle.GetStyleConfig().GetSpecialEffectDataLoads(relevantDifficultyLevelMeasurement);
		if (relevantDifficultyLevelMeasurement.DifficultyValue >= 8.0 || relevantDifficultyLevelMeasurement.StarRating != 1)
		{
			specialEffectDataLoads.AddRange((from e in UnitExtensions.GetAllDamageElements()
				select new ElementEffectData
				{
					ElementType = e
				}).Cast<ISpecialEffectDataLoad>());
		}
		List<ISpecialEffectDataLoad> list = FurtherSpecialEffectsFilter(specialEffectDataLoads, relevantDifficultyLevelMeasurement);
		if (relevantDifficultyLevelMeasurement.StarRating == 2)
		{
			List<SpecialEffectPresence> minibossSpecialEffectsPresences = GetMinibossSpecialEffectsPresences();
			if (minibossSpecialEffectsPresences.Any())
			{
				SpecialEffectPresence specialEffectPresence = minibossSpecialEffectsPresences.WeightedRandomSelect();
				foreach (ISpecialEffectDataLoad effect in specialEffectPresence.SpecialEffectDataLoads)
				{
					if (list.All((ISpecialEffectDataLoad r) => r.GetSpecialEffectType() != effect.GetSpecialEffectType()))
					{
						list.Add(effect);
					}
				}
			}
		}
		if (relevantDifficultyLevelMeasurement.StarRating == -1)
		{
			List<SpecialEffectPresence> minibossSpecialEffectsPresences2 = GetMinibossSpecialEffectsPresences();
			if (minibossSpecialEffectsPresences2.Any())
			{
				SpecialEffectPresence specialEffectPresence2 = minibossSpecialEffectsPresences2.WeightedRandomSelect();
				foreach (ISpecialEffectDataLoad effect2 in specialEffectPresence2.SpecialEffectDataLoads)
				{
					if (list.All((ISpecialEffectDataLoad r) => r.GetSpecialEffectType() != effect2.GetSpecialEffectType()))
					{
						list.Add(effect2);
					}
				}
			}
		}
		if (relevantDifficultyLevelMeasurement.DifficultyValue <= 140.0 && relevantDifficultyLevelMeasurement.StarRating == 1)
		{
			list.Add(new NegativeEffectSpeedupData
			{
				DecreaseRate = 0.4
			});
		}
		else
		{
			list.Add(new NegativeEffectSpeedupData
			{
				DecreaseRate = 0.6
			});
		}
		return list;
	}

