public static Dictionary<AttributeRetrievalLevel, Dictionary<AttributeType, Dictionary<ModificationType, double?>>> GetValues(this List<AttributeModifier> modifiers)
	{
		Dictionary<AttributeRetrievalLevel, Dictionary<AttributeType, Dictionary<ModificationType, double?>>> dictionary = new Dictionary<AttributeRetrievalLevel, Dictionary<AttributeType, Dictionary<ModificationType, double?>>>();
		List<AttributeModifier> modifiers2 = modifiers.Where((AttributeModifier m) => m.AttributeModifierType == AttributeModifierType.Normal).ToList();
		RetrieveValues(AttributeRetrievalLevel.Naked, modifiers2, dictionary);
		List<AttributeModifier> modifiers3 = modifiers.Where((AttributeModifier a) => a.AttributeModifierType == AttributeModifierType.Gear || a.AttributeModifierType == AttributeModifierType.Embeded || a.AttributeModifierType == AttributeModifierType.Growth).ToList();
		RetrieveValues(AttributeRetrievalLevel.Gear, modifiers3, dictionary);
		List<AttributeModifier> modifiers4 = modifiers.Where((AttributeModifier a) => a.AttributeModifierType == AttributeModifierType.SetBonus).ToList();
