private static void RetrieveValues(AttributeRetrievalLevel level, List<AttributeModifier> modifiers, Dictionary<AttributeRetrievalLevel, Dictionary<AttributeType, Dictionary<ModificationType, double?>>> values)
	{
		values[level] = new Dictionary<AttributeType, Dictionary<ModificationType, double?>>();
		foreach (AttributeType allAttributeType in ItemExtensions.AllAttributeTypes)
		{
			AttributeType type = allAttributeType;
			List<AttributeModifier> source = modifiers.Where((AttributeModifier a) => a.AttributeType == type).ToList();
			values[level][type] = new Dictionary<ModificationType, double?>();
			values[level][type][ModificationType.Addition] = source.Where((AttributeModifier a) => a.ModificationType == ModificationType.Addition).Sum((AttributeModifier a) => a.Value);
			values[level][type][ModificationType.Multiplication] = source.Where((AttributeModifier a) => a.ModificationType == ModificationType.Multiplication).Sum((AttributeModifier a) => a.Value);
			List<AttributeModifier> source2 = source.Where((AttributeModifier a) => a.ModificationType == ModificationType.Replacement).ToList();
			if (source2.Any())
			{
				values[level][type][ModificationType.Replacement] = source2.Last().Value;
			}
			else
			{
				values[level][type][ModificationType.Replacement] = null;
			}
		}
	}

